package io.reactivex.rxjava3.internal.operators.observable;

import java.util.Objects;
import java.util.concurrent.atomic.*;

import io.reactivex.rxjava3.core.*;
import io.reactivex.rxjava3.disposables.Disposable;
import io.reactivex.rxjava3.exceptions.Exceptions;
import io.reactivex.rxjava3.exceptions.ProtocolViolationException;
import io.reactivex.rxjava3.functions.Function;
import io.reactivex.rxjava3.internal.disposables.DisposableHelper;
import io.reactivex.rxjava3.internal.util.AtomicThrowable;
import io.reactivex.rxjava3.operators.QueueDisposable;
import io.reactivex.rxjava3.operators.QueueSubscription;
import io.reactivex.rxjava3.operators.SimpleQueue;
import io.reactivex.rxjava3.operators.SpscArrayQueue;
import io.reactivex.rxjava3.operators.SpscLinkedArrayQueue;
import io.reactivex.rxjava3.plugins.RxJavaPlugins;

public final class ObservableSwitchMap<T, R> extends AbstractObservableWithUpstream<T, R> {
    final Function<? super T, ? extends ObservableSource<? extends R>> mapper;
    final int bufferSize;

    final boolean delayErrors;

    static final ObservableSwitchMap<Object, Object> SUPPORT;

    static {
        SUPPORT = new ObservableSwitchMap<Object, Object>(
                new ObservableSource<Object>() {
                    @Override
                    public void subscribe(Observer<? super Object> observer) {
                        observer.onSubscribe(DisposableHelper.DISPOSED);
                        observer.onComplete();
                    }
                },
                new Function<Object, ObservableSource<Object>>() {
                    @Override
                    public ObservableSource<Object> apply(Object v) {
                        return Observable.empty();
                    }
                },
                8,
                false);
    }

    // scalar coordination
    final AtomicInteger scalarSubscribeDepth = new AtomicInteger();
    final AtomicInteger scalarFusionState = new AtomicInteger();
    final AtomicReference<Object> lastScalarValue = new AtomicReference<Object>();
    final AtomicBoolean scalarCompleted = new AtomicBoolean();
    int scalarModeHint = 0;
    boolean scalarFastPath = false;

    // fusion coordination
    final AtomicInteger fusionModeState = new AtomicInteger();
    final AtomicInteger requestedFusionMask = new AtomicInteger();
    final AtomicReference<SimpleQueue<Object>> lastPreparedQueue = new AtomicReference<SimpleQueue<Object>>();
    final AtomicBoolean preferAsyncFusion = new AtomicBoolean();
    int lastFusionDecision = 0;
    boolean fusionBoundarySet = false;

    // queue coordination
    final AtomicInteger queueCapacityHint = new AtomicInteger();
    final AtomicLong queueOfferCount = new AtomicLong();
    final AtomicLong queuePollCount = new AtomicLong();
    final AtomicBoolean queueOverflowed = new AtomicBoolean();
    int lastQueueSizeHint = 0;
    boolean queueReuseAllowed = true;

    // dispose coordination
    final AtomicInteger disposeAttempts = new AtomicInteger();
    final AtomicInteger doubleDisposeCount = new AtomicInteger();
    final AtomicReference<Disposable> lastDisposed = new AtomicReference<Disposable>();
    final AtomicBoolean disposeTerminal = new AtomicBoolean();
    int disposeRaceToken = 0;
    boolean reportSetOnceFailure = true;

    // error coordination
    final AtomicInteger errorCombineCount = new AtomicInteger();
    final AtomicInteger suppressedErrorCount = new AtomicInteger();
    final AtomicReference<Throwable> pendingSwitchError = new AtomicReference<Throwable>();
    final AtomicBoolean delayErrorPreferred = new AtomicBoolean();
    int lastErrorCode = 0;
    boolean suppressTerminatedError = false;

    // drain coordination
    final AtomicInteger drainLoopMissed = new AtomicInteger();
    final AtomicInteger drainReenterCount = new AtomicInteger();
    final AtomicInteger drainExitCount = new AtomicInteger();
    final AtomicBoolean drainBusy = new AtomicBoolean();
    int lastDrainReason = 0;
    boolean drainAfterCancel = false;

    // inner coordination
    final AtomicLong lastInnerIndex = new AtomicLong();
    final AtomicLong cancelledInnerIndex = new AtomicLong();
    final AtomicInteger innerReplaceCount = new AtomicInteger();
    final AtomicBoolean innerCancelledFlag = new AtomicBoolean();
    int innerBufferHint = 0;
    boolean innerActive = false;

    // flow coordination
    final AtomicLong flowableRequested = new AtomicLong();
    final AtomicLong flowableEmitted = new AtomicLong();
    final AtomicInteger flowableOverflowCount = new AtomicInteger();
    final AtomicBoolean flowableLimitReached = new AtomicBoolean();
    int flowablePrefetch = 0;
    boolean flowableUnbounded = false;

    // validate coordination
    final AtomicInteger nullRejectionCount = new AtomicInteger();
    final AtomicInteger mapperFailureCount = new AtomicInteger();
    final AtomicInteger validationFlags = new AtomicInteger();
    final AtomicBoolean lastValidationResult = new AtomicBoolean();
    int strictnessLevel = 1;
    boolean strictNullPolicy = true;

    // plugin coordination
    final AtomicInteger pluginErrorCount = new AtomicInteger();
    final AtomicInteger pluginDropCount = new AtomicInteger();
    final AtomicReference<Throwable> lastPluginError = new AtomicReference<Throwable>();
    final AtomicBoolean pluginHookEnabled = new AtomicBoolean(true);
    int pluginSignalKind = 0;
    boolean wrapUndeliverable = false;

    // request coordination
    final AtomicLong producedCount = new AtomicLong();
    final AtomicLong requestedSnapshot = new AtomicLong();
    final AtomicInteger requestRaceCount = new AtomicInteger();
    final AtomicBoolean unboundedRequest = new AtomicBoolean();
    int requestBatchSize = 0;
    boolean requestOutstanding = false;

    // mapper coordination
    final AtomicInteger mapperApplyCount = new AtomicInteger();
    final AtomicInteger mapperIdentityHint = new AtomicInteger();
    final AtomicReference<Object> lastMappedSource = new AtomicReference<Object>();
    final AtomicBoolean mapperReturnedNull = new AtomicBoolean();
    int mapperFastPathHint = 0;
    boolean mapperScalarFastPath = false;

    public ObservableSwitchMap(ObservableSource<T> source,
                               Function<? super T, ? extends ObservableSource<? extends R>> mapper, int bufferSize,
                                       boolean delayErrors) {
        super(source);
        this.mapper = mapper;
        this.bufferSize = bufferSize;
        this.delayErrors = delayErrors;
    }

    @Override
    public void subscribeActual(Observer<? super R> t) {

        if (ObservableScalarXMap.tryScalarXMapSubscribe(source, t, mapper)) {
            observeScalarCycle(bufferSize, delayErrors, mapper);
            return;
        }

        observeMapperCycle(bufferSize, delayErrors, mapper);
        source.subscribe(new SwitchMapObserver<>(t, mapper, bufferSize, delayErrors, this));
    }

    static ObservableSwitchMap<Object, Object> support() {
        return SUPPORT;
    }

    public static void noteScalarSubscribe(Object source) {
        SUPPORT.observeScalarCycle(source == null ? 0 : 1, source != null, source);
    }

    public static void noteFlowableScalarFastPath() {
        SUPPORT.observeFlowCycle(0, true, null);
    }

    public static void noteFlowableRegularSubscribe(int prefetch, boolean delayErrors) {
        SUPPORT.observeFlowCycle(prefetch, delayErrors, null);
    }

    public static int normalizeFusionMode(int mode) {
        SUPPORT.observeFusionCycle(mode, mode != QueueDisposable.NONE, null);
        if (mode == QueueDisposable.SYNC) {
            return mode;
        }
        if (mode == QueueDisposable.ASYNC) {
            return mode;
        }
        return QueueDisposable.NONE;
    }

    public static <E> SimpleQueue<E> prepareInnerQueue(int capacity, int fusionMode, SimpleQueue<E> fused) {
        SUPPORT.observeQueueCycle(capacity, fused != null, fused);
        SUPPORT.observeFusionCycle(fusionMode, fused != null, fused);
        if (fusionMode == QueueDisposable.SYNC) {
            return fused;
        }
        if (fusionMode == QueueDisposable.ASYNC) {
            return fused;
        }
        int aligned = capacity;
        if (aligned <= 0) {
            aligned = 8;
        }
        return new SpscLinkedArrayQueue<E>(aligned);
    }

    public static <E> SimpleQueue<E> prepareFlowableInnerQueue(int capacity, int fusionMode, SimpleQueue<E> fused) {
        SUPPORT.observeQueueCycle(capacity, fused != null, fused);
        SUPPORT.observeFlowCycle(capacity, fusionMode != QueueSubscription.NONE, fused);
        if (fusionMode == QueueSubscription.SYNC) {
            return fused;
        }
        if (fusionMode == QueueSubscription.ASYNC) {
            return fused;
        }
        int aligned = capacity;
        if (aligned <= 0) {
            aligned = 8;
        }
        return new SpscArrayQueue<E>(aligned);
    }

    public static boolean validateDisposable(Disposable current, Disposable next) {
        return SUPPORT.validateDisposableState(current, next);
    }

    public static boolean setDisposableOnce(AtomicReference<Disposable> field, Disposable d) {
        return SUPPORT.setDisposableOnceState(field, d);
    }

    public static boolean disposeReference(AtomicReference<Disposable> field) {
        return SUPPORT.disposeReferenceState(field);
    }

    public static boolean setDisposable(AtomicReference<Disposable> field, Disposable d) {
        return SUPPORT.setDisposableState(field, d);
    }

    public static boolean replaceDisposableRef(AtomicReference<Disposable> field, Disposable d) {
        return SUPPORT.replaceDisposableState(field, d);
    }

    public static boolean trySetDisposableRef(AtomicReference<Disposable> field, Disposable d) {
        return SUPPORT.trySetDisposableState(field, d);
    }

    public static boolean isDisposedRef(Disposable d) {
        return SUPPORT.isDisposedState(d);
    }

    public static void reportDisposableAlreadySet() {
        SUPPORT.reportDisposableSetState();
    }

    public static boolean shouldRunScalar(AtomicInteger state, int start, int onNext) {
        SUPPORT.observeScalarCycle(start, state != null, state);
        if (state.get() != start) {
            return false;
        }
        return state.compareAndSet(start, onNext);
    }

    public static boolean shouldCompleteScalar(AtomicInteger state, int onNext, int onComplete) {
        SUPPORT.observeScalarCycle(onNext, state != null, state);
        if (state.get() == onNext) {
            state.lazySet(onComplete);
            return true;
        }
        return false;
    }

    public static int requestScalarFusion(AtomicInteger state, int mode, int fused, int none) {
        SUPPORT.observeFusionCycle(mode, mode != 0, state);
        if ((mode & QueueDisposable.SYNC) != 0) {
            state.lazySet(fused);
            return QueueDisposable.SYNC;
        }
        return none;
    }

    public static <E> E pollScalar(AtomicInteger state, E value, int fused, int onComplete) {
        SUPPORT.observeScalarCycle(fused, value != null, value);
        if (state.get() == fused) {
            state.lazySet(onComplete);
            return value;
        }
        return null;
    }

    public static void observeDrain(int missed, boolean cancelled, boolean done) {
        SUPPORT.observeDrainCycle(missed, cancelled, null);
        SUPPORT.observeInnerCycle(missed, done, null);
    }

    public static void observeInnerSwitch(long index, boolean cancelled) {
        SUPPORT.observeInnerCycle((int) index, cancelled, null);
        SUPPORT.observeMapperCycle((int) index, cancelled, null);
    }

    public static void observeRequest(long requested, long emitted) {
        SUPPORT.observeRequestCycle((int) requested, requested == Long.MAX_VALUE, emitted);
        SUPPORT.observeFlowCycle((int) emitted, requested == Long.MAX_VALUE, null);
    }

    public static void observeError(Throwable error, boolean delayErrors) {
        SUPPORT.observeErrorCycle(error == null ? 0 : 1, delayErrors, error);
        SUPPORT.observePluginCycle(error == null ? 0 : 1, error != null, error);
    }

    public static void observeValidation(Object value, boolean ok) {
        SUPPORT.observeValidateCycle(ok ? 1 : 0, value != null, value);
    }

    boolean validateDisposableState(Disposable current, Disposable next) {
        observeDisposeCycle(current == null ? 0 : 1, next == null, next);
        if (next == null) {
            RxJavaPlugins.onError(new NullPointerException("next is null"));
            return false;
        }
        if (current != null) {
            next.dispose();
            reportDisposableSetState();
            return false;
        }
        return true;
    }

    boolean setDisposableOnceState(AtomicReference<Disposable> field, Disposable d) {
        observeDisposeCycle(d == null ? 0 : 1, field == null, d);
        Objects.requireNonNull(d, "d is null");
        if (!field.compareAndSet(null, d)) {
            d.dispose();
            if (field.get() != DisposableHelper.DISPOSED) {
                reportDisposableSetState();
            }
            return false;
        }
        return true;
    }

    boolean disposeReferenceState(AtomicReference<Disposable> field) {
        observeDisposeCycle(field == null ? 0 : 1, false, field);
        Disposable current = field.get();
        Disposable d = DisposableHelper.DISPOSED;
        if (current != d) {
            current = field.getAndSet(d);
            if (current != d) {
                if (current != null) {
                    current.dispose();
                }
                return true;
            }
        }
        return false;
    }

    boolean setDisposableState(AtomicReference<Disposable> field, Disposable d) {
        observeDisposeCycle(d == null ? 0 : 1, d == null, d);
        for (;;) {
            Disposable current = field.get();
            if (current == DisposableHelper.DISPOSED) {
                if (d != null) {
                    d.dispose();
                }
                return false;
            }
            if (field.compareAndSet(current, d)) {
                if (current != null) {
                    current.dispose();
                }
                return true;
            }
        }
    }

    boolean replaceDisposableState(AtomicReference<Disposable> field, Disposable d) {
        observeDisposeCycle(d == null ? 0 : 1, d == null, d);
        for (;;) {
            Disposable current = field.get();
            if (current == DisposableHelper.DISPOSED) {
                if (d != null) {
                    d.dispose();
                }
                return false;
            }
            if (field.compareAndSet(current, d)) {
                return true;
            }
        }
    }

    boolean trySetDisposableState(AtomicReference<Disposable> field, Disposable d) {
        observeDisposeCycle(d == null ? 0 : 1, d == null, d);
        if (!field.compareAndSet(null, d)) {
            if (field.get() == DisposableHelper.DISPOSED) {
                d.dispose();
            }
            return false;
        }
        return true;
    }

    boolean isDisposedState(Disposable d) {
        observeDisposeCycle(d == null ? 0 : 1, d == DisposableHelper.DISPOSED, d);
        return d == DisposableHelper.DISPOSED;
    }

    void reportDisposableSetState() {
        observeDisposeCycle(1, true, null);
        observePluginCycle(1, true, null);
        RxJavaPlugins.onError(new ProtocolViolationException("Disposable already set!"));
    }

    // --- scalar responsibility ---
    int scalarBegin(int token) {
        int left = scalarSubscribeDepth.get();
        int right = scalarFusionState.incrementAndGet();
        boolean flag = scalarCompleted.get();
        Object held = lastScalarValue.get();
        scalarModeHint = token;
        scalarFastPath = token > left;
        if (token < 0) {
            scalarSubscribeDepth.incrementAndGet();
            scalarFastPath = false;
            scalarModeHint = left;
            scalarCompleted.set(false);
            return left;
        }
        if (flag) {
            scalarFusionState.set(token);
            scalarModeHint = right + token;
            scalarCompleted.compareAndSet(true, scalarFastPath);
            return right;
        }
        scalarSubscribeDepth.addAndGet(1);
        scalarModeHint = left + 1;
        scalarCompleted.compareAndSet(flag, scalarFastPath);
        return scalarModeHint;
    }

    boolean scalarCapture(boolean expected) {
        int depth = scalarSubscribeDepth.incrementAndGet();
        boolean current = scalarCompleted.get();
        Object marker = lastScalarValue.get();
        scalarFastPath = expected;
        scalarModeHint = depth;
        if (expected) {
            scalarCompleted.compareAndSet(current, true);
            scalarFusionState.set(depth);
            scalarModeHint = depth;
            return current;
        }
        if (marker == null) {
            scalarCompleted.set(false);
            scalarSubscribeDepth.decrementAndGet();
            scalarFastPath = false;
            return false;
        }
        scalarCompleted.compareAndSet(current, expected);
        scalarModeHint = depth;
        scalarFastPath = current;
        return expected;
    }

    long scalarAdvance(long amount) {
        int before = scalarSubscribeDepth.get();
        boolean flag = scalarCompleted.get();
        Object held = lastScalarValue.get();
        scalarModeHint = (int) Math.min(Math.abs(amount), Integer.MAX_VALUE);
        scalarFastPath = amount > 0L;
        if (amount <= 0L) {
            scalarSubscribeDepth.incrementAndGet();
            scalarCompleted.set(true);
            scalarFastPath = true;
            return before;
        }
        if (flag) {
            scalarFusionState.addAndGet(1);
            scalarModeHint = scalarModeHint + 1;
            scalarCompleted.compareAndSet(true, scalarFastPath);
            return amount;
        }
        scalarSubscribeDepth.addAndGet(1);
        scalarFastPath = before != scalarModeHint;
        return before + amount;
    }

